  "res.ocrUsed": "قُرئت الصفحات الممسوحة بالتعرّف الضوئي. راجع الأسماء والأرقام مقابل الأصل.",
  "res.ocrSkipped": "تعذّر بدء التعرّف الضوئي، فحُوِّلت الصفحات الممسوحة دون نصها. إن كنت غير متصل، فحاول مجددًا عند الاتصال.",
  "res.unrestricted": "كانت في الأصل قيود وضعها مؤلفه، مثل منع الطباعة أو النسخ. الملف الجديد لا ينقلها.",
  "feat.f3b": "يضيف التعرّف الضوئي طبقة نصية غير مرئية بـ123 لغة، منها الصينية والعربية والهندية، وبعدة لغات معًا في الصفحات التي تمزج بينها.",
  "lic.lgpl": "تُوزَّع مكتبتا libheif وlibde265، اللتان تفتحان صور HEIC في المتصفحات التي لا تستطيع ذلك، بموجب رخصة GNU Lesser General Public License 3.0. تعملان كملفين منفصلين (heif/libheif.js وheif/libheif.wasm) لا يُحمَّلان إلا حين تحتاجهما صورة HEIC، ويمكنك استبدالهما بنسخة من بنائك. وشيفرتهما المصدرية متاحة مجانًا من الروابط أعلاه.",
  "ws.bigBatch": "يبلغ مجموع هذه الملفات {size}، وهو حجم كبير بالنسبة إلى ذاكرة هذا الجهاز. إذا تباطأت الصفحة أو توقفت، فعالجها على دفعات أصغر.",
