  "opt.sanLinks": "إزالة الروابط إلى مواقع الويب والملفات الأخرى",
  "opt.sanMetadata": "إزالة بيانات التعريف والبيانات المخفية",
  "opt.sanForms": "تثبيت حقول النماذج",
  "res.bookmarks": "{n|zero:لم تُنشأ أي إشارة مرجعية|one:أُنشئت إشارة مرجعية واحدة|two:أُنشئت إشارتان مرجعيتان|few:أُنشئت # إشارات مرجعية|many:أُنشئت # إشارة مرجعية|other:أُنشئت # إشارة مرجعية} من العناوين.",
  "res.bookmarksNone": "لم يُعثر على أي عناوين، لذا لم تُضف أي إشارات مرجعية. إذا كان الملف ممسوحًا ضوئيًا، فشغّل «التعرّف على النص في PDF» أولًا.",
  "res.attached": "{n|zero:لم يُرفق أي ملف|one:أُرفق ملف واحد|two:أُرفق ملفان|few:أُرفقت # ملفات|many:أُرفق # ملفًا|other:أُرفق # ملف}.",
  "res.sanitized": "تمت إزالة: {list}.",
  "res.sanitizedNone": "لا شيء لإزالته: لم يُعثر على نصوص برمجية أو روابط أو ملفات مرفقة أو بيانات تعريف.",
  "res.sanitized.scripts": "النصوص البرمجية والإجراءات",
  "res.sanitized.links": "الروابط",
